import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken breast", "Tofu", "Spinach", "Beef steak",
              "Eggs", "Brown rice", "Bananas", "Quinoa"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per item ($)
    "cost": {
        "Chicken breast": 7,
        "Tofu": 7,
        "Spinach": 1,
        "Beef steak": 9,
        "Eggs": 6,
        "Brown rice": 7,
        "Bananas": 2,
        "Quinoa": 6,
    },
    # content[nutrient][food]
    "content": {
        "protein": {
            "Chicken breast": 12, "Tofu": 10, "Spinach": 11, "Beef steak": 8,
            "Eggs": 16, "Brown rice": 4, "Bananas": 4, "Quinoa": 4,
        },
        "carbs": {
            "Chicken breast": 5, "Tofu": 1, "Spinach": 30, "Beef steak": 26,
            "Eggs": 9, "Brown rice": 25, "Bananas": 16, "Quinoa": 20,
        },
        "calories": {
            "Chicken breast": 231, "Tofu": 210, "Spinach": 295, "Beef steak": 211,
            "Eggs": 232, "Brown rice": 146, "Bananas": 255, "Quinoa": 205,
        },
    },
    # daily requirements
    "requirement": {
        "protein": 91,
        "carbs": 136,
        "calories": 1563,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # x_i = number of servings/items of food i
    # assumption: domain_of_food_quantities = NonNegativeIntegers
    model.x = pyo.Var(model.F, within=pyo.NonNegativeIntegers)

    # Objective: minimize total cost sum(cost_i * x_i)
    # "how can you meet your daily dietary requirements while keeping the cost as low as possible?"
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.F)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient constraints: at least the benchmarks (>= requirement)
    # "specific benchmarks to achieve every day: 91 grams of protein, 136 grams of carbohydrates, and 1563 calories"
    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.x[f] for f in m.F) >= d["requirement"][n]

    model.nutrient = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


